drop extension if exists "pg_net";

create type "public"."report_status" as enum ('open', 'in_analysis', 'in_progress', 'completed', 'closed', 'expired');

create type "public"."states" as enum ('ac', 'al', 'ap', 'am', 'ba', 'ce', 'df', 'es', 'go', 'mt', 'ms', 'mg', 'pa', 'pb', 'pr', 'pe', 'pi', 'rj', 'rn', 'rs', 'ro', 'rr', 'sc', 'sp', 'se', 'to');


  create table "public"."cities" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "name" text,
    "state" public.states
      );


alter table "public"."cities" enable row level security;


  create table "public"."comments" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "user" bigint,
    "post" bigint,
    "text" text,
    "reply" text,
    "likes" bigint
      );


alter table "public"."comments" enable row level security;


  create table "public"."posts" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "user" bigint,
    "city" bigint,
    "likes" bigint,
    "description" text,
    "image_url" text,
    "status" public.report_status,
    "latitude" double precision,
    "longitude" double precision,
    "anonymity" boolean
      );


alter table "public"."posts" enable row level security;


  create table "public"."users" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "first_name" text,
    "last_name" text,
    "city" text,
    "email" text,
    "xp" integer,
    "level" smallint,
    "verified" boolean,
    "populatiry" bigint,
    "points" bigint
      );


alter table "public"."users" enable row level security;

CREATE UNIQUE INDEX cities_pkey ON public.cities USING btree (id);

CREATE UNIQUE INDEX comments_pkey ON public.comments USING btree (id);

CREATE UNIQUE INDEX posts_pkey ON public.posts USING btree (id);

CREATE UNIQUE INDEX users_email_key ON public.users USING btree (email);

CREATE UNIQUE INDEX users_pkey ON public.users USING btree (id);

alter table "public"."cities" add constraint "cities_pkey" PRIMARY KEY using index "cities_pkey";

alter table "public"."comments" add constraint "comments_pkey" PRIMARY KEY using index "comments_pkey";

alter table "public"."posts" add constraint "posts_pkey" PRIMARY KEY using index "posts_pkey";

alter table "public"."users" add constraint "users_pkey" PRIMARY KEY using index "users_pkey";

alter table "public"."comments" add constraint "comments_post_fkey" FOREIGN KEY (post) REFERENCES public.posts(id) not valid;

alter table "public"."comments" validate constraint "comments_post_fkey";

alter table "public"."comments" add constraint "comments_user_fkey" FOREIGN KEY ("user") REFERENCES public.users(id) not valid;

alter table "public"."comments" validate constraint "comments_user_fkey";

alter table "public"."posts" add constraint "posts_city_fkey" FOREIGN KEY (city) REFERENCES public.cities(id) not valid;

alter table "public"."posts" validate constraint "posts_city_fkey";

alter table "public"."posts" add constraint "posts_user_fkey" FOREIGN KEY ("user") REFERENCES public.users(id) not valid;

alter table "public"."posts" validate constraint "posts_user_fkey";

alter table "public"."users" add constraint "users_email_key" UNIQUE using index "users_email_key";

